export function fieldOptions(path) {
  const options = OPTIONS[path];
  if (!options) return [];
  if (path === 'DEF_METHANE%inundation_mode') return ['wetwat', 'satellite'];
  return Object.keys(options);
}

/** 参数目录条目的界面名。PFT/PC 参数的目录名是 `colm-case::pft` 里写好的正式名字；其余条目的
 *  目录名只是把 CoLM 键拆成单词，界面名一律取 [`fieldLabel`]。 */
export function catalogLabel(item, lang = 'zh') {
  const own = lang === 'en' ? item?.label_en : item?.label_zh;
  const pft = item?.scope === 'pft-type' || item?.scope === 'pc-pft-component';
  if (pft && own) return own;
  return fieldLabel(item?.raw_key ?? item?.name ?? '', lang);
}

/** 字段的界面名：有配好的中英文名就用它，没有就显示 CoLM 原名。 */
export function fieldLabel(path, lang = 'zh') {
  const exact = pick(LABELS[path], lang);
  if (exact) return exact;
  // 没配名字的字段显示去掉 DEF_/USE_SITE_/SITE_ 前缀的 CoLM 原名：拆词拼出来的「目录 · existing ·
  // srfdata」中英混杂、读不懂，原名至少清楚、能搜。参数目录里的字段都必须在 LABELS 里有名字
  // （gui/tests/labels.mjs 会查），这里只兜上游新加、还没配名字的字段。
  return path.replace(/^(DEF_|USE_SITE_|SITE_)/i, '');
}

/** 下拉框显示方案名，value 仍保持 CoLM 的原始字面量。 */
export function optionLabel(path, value, lang = 'zh') {
  const raw = String(value).replace(/^'|'$/g, '');
  const described = pick(OPTIONS[path]?.[raw], lang);
  if (described) return `${described}${lang === 'en' ? ` (${raw})` : `（${raw}）`}`;
  if (/^(\.true\.|true|\.t\.)$/i.test(raw)) return lang === 'en' ? 'Enabled' : '启用';
  if (/^(\.false\.|false|\.f\.)$/i.test(raw)) return lang === 'en' ? 'Disabled' : '关闭';
  return raw;
}

export function technicalFieldHint(path, lang = 'zh') {
  return lang === 'en' ? `CoLM key: ${path}` : `CoLM 配置键：${path}`;
}
